class DanExpandingNav{static instances=[];constructor(element){this.element=element;this.navItems=Array.from(element.querySelectorAll(".dan-expanding-nav__nav-item"));this.expandingContent=element.querySelector(".dan-expanding-nav__expanding-content");this.expandingContentItems=Array.from(element.querySelectorAll(".dan-expanding-nav__expanding-content-item"));this.expandingNavHeight=element.offsetHeight;this.expandingNavFrom=element.getAttribute("data-from");this.contentHeights=Array.from(this.expandingContentItems).map(item=>item.scrollHeight);this.openInBuilder=element.getAttribute('data-open-in-builder')=='1';this.isInBuilder=window.location.href.includes("breakdance_iframe")||window.location.href.includes("breakdance")||window.parent!==window;this.shouldKeepActive=this.isInBuilder&&this.openInBuilder;this.observer=null;this.eventListeners=[];this.init()}
init(){this.element.removeAttribute('data-flickering');if(!this.navItems.length||!this.expandingContent||!this.expandingContentItems.length){return}
this.recalculateHeights=()=>{this.contentHeights=Array.from(this.expandingContentItems).map(item=>item.scrollHeight);const activeIndex=Array.from(this.expandingContentItems).findIndex(item=>item.getAttribute('data-active')==='true');if(activeIndex!==-1&&this.expandingContent.getAttribute('data-active')==='true'){this.expandingContent.style.height=(this.contentHeights[activeIndex]+this.expandingNavHeight)+'px'}};if(this.shouldKeepActive){this.navItems[0].setAttribute('data-active','true');this.expandingContentItems[0].setAttribute('data-active','true');this.expandingContent.setAttribute('data-active','true');this.expandingContent.style.height=(this.contentHeights[0]+this.expandingNavHeight)+'px';if(this.expandingNavFrom=='top'){this.expandingContentItems[0].style.top=this.expandingNavHeight+'px'}else{this.expandingContentItems[0].style.bottom=this.expandingNavHeight+'px'}}
this.observer=new MutationObserver((mutations)=>{this.recalculateHeights()});this.expandingContentItems.forEach(item=>{this.observer.observe(item,{childList:!0,subtree:!0,characterData:!0})});this.setupEventListeners()}
setupEventListeners(){this.navItems.forEach((navItem,index)=>{const activateItem=()=>{this.navItems.forEach((navItem)=>{navItem.removeAttribute('data-active')});this.expandingContentItems.forEach((expandingContentItem)=>{expandingContentItem.removeAttribute('data-active')});navItem.setAttribute('data-active','true');this.expandingContentItems[index].setAttribute('data-active','true');this.expandingContent.setAttribute('data-active','true');this.expandingContent.style.height=(this.contentHeights[index]+this.expandingNavHeight)+'px';if(this.expandingNavFrom=='top'){this.expandingContentItems[index].style.top=this.expandingNavHeight+'px'}else{this.expandingContentItems[index].style.bottom=this.expandingNavHeight+'px'}};const handleKeyDown=(e)=>{if(e.key==='Enter'){activateItem()}};navItem.addEventListener('mouseenter',activateItem);navItem.addEventListener('keydown',handleKeyDown);this.eventListeners.push({element:navItem,type:'mouseenter',handler:activateItem},{element:navItem,type:'keydown',handler:handleKeyDown})});const deactivate=()=>{this.navItems.forEach((navItem)=>{navItem.removeAttribute('data-active')});this.expandingContentItems.forEach((expandingContentItem)=>{expandingContentItem.removeAttribute('data-active')});this.expandingContent.setAttribute('data-active','false');this.expandingContent.style.height='100%'};if(!this.shouldKeepActive){this.expandingContent.addEventListener('mouseleave',deactivate);this.eventListeners.push({element:this.expandingContent,type:'mouseleave',handler:deactivate});this.navItems.forEach((navItem)=>{navItem.addEventListener('focusout',deactivate);this.eventListeners.push({element:navItem,type:'focusout',handler:deactivate})})}const handleDocumentLeave=()=>{deactivate()};document.addEventListener('visibilitychange',handleDocumentLeave);window.addEventListener('beforeunload',handleDocumentLeave);this.eventListeners.push({element:document,type:'visibilitychange',handler:handleDocumentLeave},{element:window,type:'beforeunload',handler:handleDocumentLeave})}
destroy(){this.eventListeners.forEach(({element,type,handler})=>{element.removeEventListener(type,handler)});this.eventListeners=[];if(this.observer){this.observer.disconnect();this.observer=null}
if(this.expandingContent){this.expandingContent.style.height="";this.expandingContent.removeAttribute("data-active")}
this.expandingContentItems.forEach((item)=>{item.removeAttribute("data-active");item.style.top="";item.style.bottom=""});this.navItems.forEach((item)=>item.removeAttribute("data-active"));this.element=null;this.navItems=[];this.expandingContent=null;this.expandingContentItems=[];this.contentHeights=[];this.recalculateHeights=null}
static destroyAll(){DanExpandingNav.instances.forEach((instance)=>instance.destroy());DanExpandingNav.instances=[]}}
function dancepad_expanding_nav(){DanExpandingNav.destroyAll();const instances=[];document.querySelectorAll(".dan-expanding-nav").forEach((element)=>{const instance=new DanExpandingNav(element);instances.push(instance)});DanExpandingNav.instances=instances}